CREATE OR REPLACE PROCEDURE sp(para_part_id integer, para_asset_id integer, para_part_fault_id integer)
LANGUAGE plpgsql
AS $$
DECLARE
    cur CURSOR FOR SELECT * FROM Asset_Parts FOR UPDATE;
    rec Asset_Parts%ROWTYPE;
    counter integer := 0;
BEGIN
    UPDATE Asset_Parts
       SET asset_id = para_asset_id + 100
     WHERE asset_id <= para_asset_id;

    OPEN cur;

    LOOP
        FETCH cur INTO rec;
        EXIT WHEN NOT FOUND;

        IF rec.part_id >= para_part_id THEN
            UPDATE Asset_Parts
               SET asset_id = para_asset_id - 10
             WHERE CURRENT OF cur;
            counter := counter + 1;
        END IF;
    END LOOP;

    CLOSE cur;

    IF counter > 0 THEN
        UPDATE Skills_Required_To_Fix
           SET part_fault_id = para_part_fault_id;
    END IF;
END;
$$;

